select id, product_name, category, price, cost, launch_date, tags, supplier_id, sum(stock_qty) over (partition by category, brand order by launch_date asc, id asc rows between 2 preceding and current row) as last3_sum_stock_qty, count(stock_qty) over (partition by category, brand order by launch_date asc, id asc rows between 2 preceding and current row) as last3_count_stock_qty, avg(stock_qty) over (partition by category, brand order by launch_date asc, id asc rows between 2 preceding and current row) as last3_avg_stock_qty, min(stock_qty) over (partition by category, brand order by launch_date asc, id asc rows between 2 preceding and current row) as last3_min_stock_qty, row_number() over (partition by supplier_id, category order by cost asc, id asc) as row_seq from products
